sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float angle;
uniform float speed;
uniform float depthSource;
uniform float focus;
uniform float motion;
uniform float transparentEdge;
uniform float shutter;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
float4 smp(float2 p, float tr) {
    return tr > 0.5 ? texT(p) : tex(p);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float4 shot(float2 coord, float T) {
    float d = luma(tex(coord).rgb);
    if (depthSource > 0.5) d = 1.0 - d;
    float a = radians(angle);
    float2 dir = float2(cos(a), sin(a));
    float2 mv = motion < 0.5 ? dir * sin(T * speed * 6.2831853) : float2(cos(T * speed * 6.2831853), sin(T * speed * 6.2831853));
    float2 q = coord - mv * (d - focus) * amount;
    return smp(q, transparentEdge);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float4 acc = float4(0.0);
    for (int i = 0; i < 8; i++) {
        acc += shot(coord, time - shutter * 0.04 * float(i) / 7.0);
    }
    return fin(c, acc / 8.0, opacity);
}
